1	import { describe, it, expect } from "vitest";
2	import { spawnSync } from "node:child_process";
3	import { fileURLToPath } from "node:url";
4	// CLI under test (to be created in the Green phase): src/cli.ts,
5	// executed as a child process with JSON on stdin.
6	
7	const CLI_PATH = fileURLToPath(new URL("./cli.ts", import.meta.url));
8	
9	// Spawning a real process is slow compared with an in-process call, so every
10	// CLI test gets a generous timeout.
11	const CLI_TIMEOUT_MS = 30_000;
12	
13	type CliRun = {
14	  status: number | null;
15	  stdout: string;
16	  stderr: string;
17	};
18	
19	// The CLI is exercised end to end: the scenario goes in as JSON on stdin and
20	// the test only looks at what a shell would see - stdout, stderr, exit status.
21	const runCli = (scenario: unknown): CliRun => {
22	  const { status, stdout, stderr } = spawnSync("npx", ["tsx", CLI_PATH], {
23	    input: JSON.stringify(scenario),
24	    encoding: "utf8",
25	  });
26	  return { status, stdout, stderr };
27	};
28	
29	describe("claim-office CLI", () => {
30	  it(
31	    "should read a scenario from stdin and write {results:[{premium}]} to stdout for a single quote step",
32	    () => {
33	      const { stdout } = runCli({
34	        customer: { yearsWithMHPCO: 0 },
35	        steps: [{ op: "quote", items: [{ type: "sword" }] }],
36	      });
37	
38	      expect(JSON.parse(stdout)).toEqual({ results: [{ premium: 115 }] });
39	    },
40	    CLI_TIMEOUT_MS,
41	  );
42	
43	  it(
44	    "should write one result per step, in the same order as the input steps",
45	    () => {
46	      const { stdout } = runCli({
47	        customer: { yearsWithMHPCO: 0 },
48	        steps: [
49	          { op: "quote", items: [{ type: "sword" }] },
50	          { op: "quote", items: [{ type: "amulet" }] },
51	          {
52	            op: "claim",
53	            policy: 0,
54	            incident: {
55	              cause: "dragon",
56	              damages: [{ itemType: "sword", amount: 500 }],
57	            },
58	          },
59	        ],
60	      });
61	
62	      expect(JSON.parse(stdout)).toEqual({
63	        results: [
64	          { premium: 115 },
65	          { premium: 62 },
66	          { payout: 400, remainingCap: 1600 },
67	        ],
68	      });
69	    },
70	    CLI_TIMEOUT_MS,
71	  );
72	
73	  it(
74	    "should write {payout, remainingCap} for a claim step referring to an earlier quote step by index",
75	    () => {
76	      const { stdout } = runCli({
77	        customer: { yearsWithMHPCO: 0 },
78	        steps: [
79	          { op: "quote", items: [{ type: "sword" }] },
80	          {
81	            op: "claim",
82	            policy: 0,
83	            incident: {
84	              cause: "dragon",
85	              damages: [{ itemType: "sword", amount: 500 }],
86	            },
87	          },
88	        ],
89	      });
90	
91	      expect(JSON.parse(stdout).results[1]).toEqual({
92	        payout: 400,
93	        remainingCap: 1600,
94	      });
95	    },
96	    CLI_TIMEOUT_MS,
97	  );
98	
99	  it(
100	    "should exit with status 0 for a valid scenario",
101	    () => {
102	      const { status, stderr } = runCli({
103	        customer: { yearsWithMHPCO: 0 },
104	        steps: [{ op: "quote", items: [{ type: "sword" }] }],
105	      });
106	
107	      expect(status).toBe(0);
108	      expect(stderr).toBe("");
109	    },
110	    CLI_TIMEOUT_MS,
111	  );
112	  it(
113	    "should exit non-zero and write an error description to stderr, with no results on stdout, for a quote with an unknown item type",
114	    () => {
115	      const { status, stdout, stderr } = runCli({
116	        customer: { yearsWithMHPCO: 0 },
117	        steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
118	      });
119	
120	      expect(status).not.toBe(0);
121	      // A rejection is reported as a description of what was wrong, not as a
122	      // crash: the domain message reaches stderr without a stack trace.
123	      expect(stderr).toMatch(/unknown item type/i);
124	      expect(stderr).not.toContain("    at ");
125	      expect(stdout).not.toContain("results");
126	    },
127	    CLI_TIMEOUT_MS,
128	  );
129	
130	  it(
131	    "should exit non-zero and write an error description to stderr for a claim with a negative damage amount",
132	    () => {
133	      const { status, stderr } = runCli({
134	        customer: { yearsWithMHPCO: 0 },
135	        steps: [
136	          { op: "quote", items: [{ type: "sword" }] },
137	          {
138	            op: "claim",
139	            policy: 0,
140	            incident: {
141	              cause: "dragon",
142	              damages: [{ itemType: "sword", amount: -200 }],
143	            },
144	          },
145	        ],
146	      });
147	
148	      expect(status).not.toBe(0);
149	      expect(stderr).toMatch(/negative damage amount/i);
150	      expect(stderr).not.toContain("    at ");
151	    },
152	    CLI_TIMEOUT_MS,
153	  );
154	});
